-- NeuroBalance Große Arkana ADULT/de · structured from supplied source
SET NAMES utf8mb4;
INSERT INTO nb_card_text
(card_id,audience_code,language_code,content_version,title,subtitle,reflection_keywords,
 what_do_you_see,card_room,helpful_side,difficult_side,context_questions_json,
 own_card_language,possible_next_step,status_code)
VALUES
('major-00','ADULT','de','0.1.0','Der Narr','Ein Schritt ins noch Unbekannte',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Narr steht an einer Schwelle. Vor ihm liegt ein Weg, den er noch nicht vollständig kennt. Vielleicht wirkt dieser Moment auf dich mutig, leicht, unsicher oder unvernünftig. Entscheidend ist nicht die übliche Deutung, sondern was du heute in diesem Aufbruch wahrnimmst.','Neugier, Offenheit und spielerisches Ausprobieren können einen Anfang ermöglichen. Du musst noch nicht den gesamten Weg kennen. Manchmal genügt ein erster kleiner Schritt.','Offenheit kann unter unübersichtlichen Bedingungen überfordern oder Risiken verdecken. Vielleicht brauchst du nicht weniger Mut, sondern mehr Information, Zeit, Unterstützung oder Sicherheit.','["Gibt es etwas, das du gern ausprobieren möchtest?", "Welche Bedingungen würden den ersten Schritt sicherer machen?", "Möchtest du losgehen - oder glaubst du, losgehen zu müssen?"]','Was bedeutet „ins Unbekannte gehen“ heute für dich?','Du könntest den Weg zunächst erkunden, ohne dich für die gesamte Reise entscheiden zu müssen.','draft-review'),
('major-01','ADULT','de','0.1.0','Der Magier','Mit dem arbeiten, was bereits da ist',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Vor dem Magier liegen verschiedene Werkzeuge. Die Karte kann den Blick darauf lenken, was dir bereits zur Verfügung steht: Wissen, Erfahrung, Beziehungen, Ideen oder eine Fähigkeit, die du bisher unterschätzt hast.','Wenn du deine Möglichkeiten erkennst und bewusst verbindest, kann aus einer Idee Handlung werden. Wirksamkeit beginnt nicht erst bei Perfektion.','Gestaltungskraft kann in Druck umschlagen, wenn du alles kontrollieren oder allein bewältigen möchtest. Auch ein vorhandenes Werkzeug muss nicht unter allen Bedingungen passen.','["Welche Fähigkeiten oder Hilfsmittel sind bereits da?", "Was davon passt zu deiner aktuellen Situation?", "Wo wäre Zusammenarbeit hilfreicher als alleinige Kontrolle?"]','Welche Form von Wirksamkeit möchtest du heute erleben?','Du könntest ein vorhandenes Werkzeug auswählen und damit einen überschaubaren Versuch machen.','draft-review'),
('major-02','ADULT','de','0.1.0','Die Hohepriesterin','Hören, bevor du handelst',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Die Hohepriesterin verweist auf Wahrnehmungen, die noch keine fertigen Worte haben. Vielleicht gibt es etwas, das du bereits spürst, obwohl du es noch nicht erklären oder beweisen kannst.','Stille, Beobachtung und Intuition können Zugang zu feinen Signalen schaffen. Nicht jede Erkenntnis muss sofort nach außen getragen werden.','Rückzug kann schützen, aber auch isolieren. Intuition ist eine Wahrnehmungsquelle, keine unfehlbare Wahrheit; sie darf neben Informationen und anderen Perspektiven stehen.','["Was weißt du vielleicht schon, ohne es erklären zu können?", "Brauchst du gerade mehr Stille oder mehr Austausch?", "Welche Beobachtung möchtest du noch nicht vorschnell deuten?"]','Wie fühlt sich deine innere Stimme heute an?','Du könntest eine Wahrnehmung notieren, ohne sofort eine Entscheidung daraus abzuleiten.','draft-review'),
('major-03','ADULT','de','0.1.0','Die Kaiserin','Nähren, was wachsen möchte',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Die Kaiserin öffnet einen Raum für Fürsorge, Körperlichkeit, Kreativität und Fülle. Sie kann fragen, was in deinem Leben Nahrung, Schutz oder Aufmerksamkeit braucht.','Wachstum wird möglich, wenn Bedürfnisse wahrgenommen und Ressourcen zugänglich werden. Genuss und Fürsorge dürfen einen eigenen Wert besitzen.','Fürsorge kann erschöpfen, wenn sie nur anderen gilt. Fülle kann sich auch wie Übermaß anfühlen. Entscheidend ist, was unter deinen Bedingungen wirklich nährt.','["Was braucht gerade Pflege oder Zeit?", "Welche Form von Fülle tut dir gut - und welche wird zu viel?", "Wo darfst du selbst empfangen, statt nur zu geben?"]','Was bedeutet Fürsorge heute für dich?','Du könntest einer körperlichen oder emotionalen Bedürfnislage bewusst Raum geben.','draft-review'),
('major-04','ADULT','de','0.1.0','Der Kaiser','Struktur, die Halt geben kann',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Kaiser steht für Ordnung, Grenzen und Verantwortung. Die Karte kann sichtbar machen, welche Struktur trägt und wo Zuständigkeit Klarheit schafft.','Verlässliche Regeln, klare Grenzen und vorhersehbare Abläufe können Sicherheit schaffen und Handlung ermöglichen.','Struktur kann einengen, wenn sie wichtiger wird als die Menschen, denen sie dienen soll. Kontrolle ist nicht dasselbe wie Sicherheit.','["Welche Struktur entlastet dich gerade?", "Welche Grenze muss klarer werden?", "Dient die Regel noch ihrem ursprünglichen Zweck?"]','Wie möchtest du Verantwortung und Sicherheit miteinander verbinden?','Du könntest eine einzige hilfreiche Grenze oder Zuständigkeit klar benennen.','draft-review'),
('major-05','ADULT','de','0.1.0','Der Hierophant','Überliefertes prüfen und einordnen',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Hierophant begegnet Wissen, Traditionen, Gemeinschaften und Regeln. Er kann dazu einladen, zu prüfen, was dir Orientierung gibt und was du nur übernommen hast.','Gemeinsame Sprache und geteiltes Wissen können Zugehörigkeit schaffen. Erfahrungen anderer müssen nicht allein wiederholt werden.','Traditionen können Menschen ausschließen oder ihre individuellen Wege überdecken. Eine Regel ist nicht automatisch richtig, nur weil sie lange besteht.','["Welche Werte tragen dich wirklich?", "Wo gibt eine Gemeinschaft Orientierung?", "Welche übernommene Regel möchtest du neu prüfen?"]','Was möchtest du bewahren - und was möchtest du anders gestalten?','Du könntest eine wichtige Regel nach ihrem Nutzen für Mensch und Situation befragen.','draft-review'),
('major-06','ADULT','de','0.1.0','Die Liebenden','Eine Wahl in Verbindung',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Die Liebenden stehen für Beziehung, Resonanz und Entscheidungen, die etwas über Werte sichtbar machen. Das kann romantische Nähe betreffen, aber ebenso Freundschaft, Zusammenarbeit oder die Beziehung zu dir selbst.','Verbindung kann Räume öffnen, in denen Unterschiede bestehen dürfen. Eine stimmige Wahl verbindet häufig mehrere wichtige Teile deiner Wirklichkeit.','Nähe kann Selbstverlust bedeuten, wenn Bedürfnisse oder Grenzen unsichtbar werden. Nicht jede Verbindung ist unter allen Bedingungen tragfähig.','["Was verbindet dich - und was unterscheidet dich?", "Welche Werte möchtest du in dieser Wahl wiederfinden?", "Kannst du verbunden bleiben, ohne dich selbst zu verlassen?"]','Welche Art von Verbindung fühlt sich heute stimmig an?','Du könntest benennen, was in einer Verbindung sowohl dir als auch dem Gegenüber wichtig ist.','draft-review'),
('major-07','ADULT','de','0.1.0','Der Wagen','Die eigene Richtung wählen',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Wagen bündelt unterschiedliche Kräfte zu einer Bewegung. Die Karte kann fragen, wohin du wirklich möchtest und welche inneren oder äußeren Kräfte dabei in verschiedene Richtungen ziehen.','Ausrichtung kann Energie verfügbar machen. Du musst nicht schnell sein, um dich zu bewegen; auch eine bewusste Kurskorrektur ist Fortschritt.','Entschlossenheit kann Bedürfnisse überfahren. Bewegung ohne passende Bedingungen verbraucht möglicherweise mehr Kraft, als sie trägt.','["Wohin möchtest du deine Energie lenken?", "Welche Kräfte ziehen gerade gegeneinander?", "Welches Tempo ist für dich nachhaltig?"]','Woran würdest du erkennen, dass dies deine Richtung ist?','Du könntest Richtung und Tempo getrennt voneinander entscheiden.','draft-review'),
('major-08','ADULT','de','0.1.0','Die Kraft','Sanfte Stärke',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Die Kraft zeigt Stärke nicht als Bezwingen, sondern als Beziehung zur eigenen Energie. Mut kann leise sein: bleiben, regulieren, um Hilfe bitten oder eine Grenze schützen.','Selbstvertrauen kann wachsen, wenn starke Gefühle nicht bekämpft, sondern verstanden und begleitet werden.','Stärke wird belastend, wenn sie mit ständigem Funktionieren verwechselt wird. Du musst nicht alles aushalten, um stark zu sein.','["Welche Kraft ist gerade in dir spürbar?", "Braucht sie Ausdruck, Schutz oder Beruhigung?", "Wo wäre Sanftheit wirksamer als Druck?"]','Was bedeutet Stärke für dich, wenn niemand zusieht?','Du könntest deine Kraft heute dosieren, statt sie vollständig einsetzen zu müssen.','draft-review'),
('major-09','ADULT','de','0.1.0','Der Eremit','Der eigene Raum als Orientierung',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Eremit trägt sein Licht in die Stille. Die Karte kann freiwilligen Rückzug, Konzentration und die Suche nach dem eigenen Rhythmus sichtbar machen.','Alleinsein kann Reize reduzieren und Zugang zu eigenen Gedanken schaffen. Rückzug darf eine Ressource sein und muss kein Mangel an Verbindung bedeuten.','Rückzug kann zur Isolation werden, wenn Verbindung fehlt, obwohl sie gebraucht wird. Manchmal braucht Orientierung nicht mehr Einsamkeit, sondern eine verlässliche Begleitung.','["Wonach suchst du in der Stille?", "Ist dein Rückzug gerade gewählt oder erzwungen?", "Welche Form von Verbindung darf erreichbar bleiben?"]','Was kannst du nur wahrnehmen, wenn es stiller wird?','Du könntest einen geschützten Zeitraum für dich schaffen und zugleich einen Rückweg offenlassen.','draft-review'),
('major-10','ADULT','de','0.1.0','Das Rad des Schicksals','Bewegung in einem größeren Zyklus',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Das Rad erinnert daran, dass Zustände sich verändern. Nicht jede Bewegung wird von dir verursacht oder kontrolliert. Manches entsteht durch Zeit, Zufall, Beziehungen oder veränderte Bedingungen.','Zyklen können entlasten: Ein gegenwärtiger Zustand ist nicht deine gesamte Geschichte. Veränderung kann neue Möglichkeiten öffnen.','Unvorhersehbarkeit kann verunsichern. Die Vorstellung, alles geschehe aus einem bestimmten Grund, kann reale Belastungen und Verantwortung unsichtbar machen.','["Was verändert sich gerade?", "Was liegt in deinem Einfluss - und was nicht?", "Welche frühere Veränderung hat später etwas Neues ermöglicht?"]','Wie erlebst du Bewegung, die du nicht vollständig steuerst?','Du könntest Einfluss und Nicht-Einfluss voneinander trennen und deine Energie entsprechend verteilen.','draft-review'),
('major-11','ADULT','de','0.1.0','Die Gerechtigkeit','Fairness im wirklichen Kontext',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Die Gerechtigkeit lädt zum Abwägen ein. Dabei geht es nicht nur um gleiche Regeln, sondern darum, unterschiedliche Voraussetzungen und Folgen sichtbar zu machen.','Klarheit, Verantwortung und nachvollziehbare Entscheidungen können Vertrauen schaffen. Fairness darf auch bedeuten, verschiedene Menschen unterschiedlich zu unterstützen.','Urteile werden problematisch, wenn Kontext fehlt oder Regeln scheinbar neutral sind, aber ungleiche Wirkungen haben. Auch Selbstkritik kann unverhältnismäßig streng sein.','["Welche Informationen fehlen noch?", "Was wäre fair - auch dir selbst gegenüber?", "Wer trägt welche Verantwortung und welche Bedingungen wirkten mit?"]','Was bedeutet Gerechtigkeit in dieser konkreten Situation?','Du könntest die Entscheidung aus mindestens zwei Perspektiven und mit Blick auf ihre Folgen betrachten.','draft-review'),
('major-12','ADULT','de','0.1.0','Der Gehängte','Eine Pause verändert den Blick',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Gehängte befindet sich zwischen Bewegung und Stillstand. Die Karte kann einen Moment zeigen, in dem Handeln nicht weiterführt und ein anderer Blickwinkel entstehen darf.','Eine Pause kann neue Zusammenhänge sichtbar machen. Nicht sofort zu lösen kann eine aktive und kluge Entscheidung sein.','Warten kann belastend werden, wenn du keine Wahl oder keinen Einfluss erlebst. Loslassen darf nicht bedeuten, notwendige Unterstützung oder Veränderung aufzugeben.','["Was wird sichtbar, wenn du die Perspektive wechselst?", "Ist die Pause gewählt, notwendig oder aufgezwungen?", "Was darf ruhen, ohne vergessen zu werden?"]','Wie fühlt sich Nicht-Handeln heute für dich an?','Du könntest eine Entscheidung vertagen und festlegen, wann du sie wieder ansiehst.','draft-review'),
('major-13','ADULT','de','0.1.0','Der Tod','Ein Ende schafft einen Übergang',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Tod steht im Tarot meist nicht für ein körperliches Ende, sondern für Abschluss und tiefgreifende Veränderung. Etwas Vertrautes kann seine Form verlieren, bevor das Neue erkennbar ist.','Abschiede können Raum schaffen und Entwicklung ermöglichen. Du darfst anerkennen, dass etwas vorbei ist, ohne seine Bedeutung zu verlieren.','Veränderung kann Trauer, Angst oder Kontrollverlust auslösen. Nicht jedes Ende muss begrüßt werden; auch notwendige Übergänge dürfen schmerzen.','["Was ist möglicherweise bereits zu Ende gegangen?", "Was möchtest du würdigen, bevor du loslässt?", "Welche Unterstützung brauchst du für den Übergang?"]','Was bleibt von etwas, auch wenn seine bisherige Form endet?','Du könntest benennen, was du verabschiedest und was du bewusst mitnehmen möchtest.','draft-review'),
('major-14','ADULT','de','0.1.0','Die Mäßigkeit','Die passende Mischung finden',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Die Mäßigkeit verbindet verschiedene Elemente, ohne sie gleichzumachen. Sie fragt nach Dosierung, Übergängen und einem Gleichgewicht, das zu diesem Menschen und diesem Moment passt.','Ausgleich kann entstehen, wenn Bedürfnisse miteinander verhandelt werden. Kleine Anpassungen können wirksamer sein als ein radikaler Wechsel.','Balance ist kein dauerhafter Idealzustand. Der Anspruch, immer ausgeglichen zu sein, kann neue Belastung erzeugen. Manche Situationen brauchen keine Mitte, sondern eine klare Grenze.','["Welche Mischung tut dir gerade gut?", "Wovon brauchst du mehr, wovon weniger?", "Geht es um Balance - oder um Schutz?"]','Wie sieht deine passende Dosierung heute aus?','Du könntest eine Belastung oder Ressource in einem kleinen Schritt neu dosieren.','draft-review'),
('major-15','ADULT','de','0.1.0','Der Teufel','Bindungen und Muster sichtbar machen',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Teufel kann Verbindungen zeigen, die gleichzeitig anziehen und einengen. Gewohnheiten, Erwartungen, Ängste oder Abhängigkeiten werden sichtbar, ohne den Menschen dafür zu verurteilen.','Ein Muster zu erkennen schafft Wahlmöglichkeiten. Auch Strategien, die heute belasten, hatten vielleicht einmal eine schützende Funktion.','Scham und Schuld können Bindungen verstärken. Nicht jede belastende Situation lässt sich allein durch Willenskraft verändern; manchmal fehlen sichere Alternativen oder Unterstützung.','["Was gibt dir diese Bindung - und was kostet sie?", "Welche Funktion hatte das Muster möglicherweise einmal?", "Welche reale Alternative wäre erreichbar und sicher?"]','Wo wünschst du dir heute mehr Wahlfreiheit?','Du könntest das Muster zunächst beobachten, ohne sofort von dir zu verlangen, es vollständig zu verändern.','draft-review'),
('major-16','ADULT','de','0.1.0','Der Turm','Wenn eine bisherige Sicherheit nicht mehr trägt',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Turm zeigt einen Moment, in dem eine Vorstellung, Struktur oder Sicherheit erschüttert wird. Was bisher stabil wirkte, kann sich als unpassend oder nicht mehr haltbar zeigen.','Klarheit kann entstehen, wenn etwas Verdecktes sichtbar wird. Ein Zusammenbruch kann Raum für ehrlichere und tragfähigere Strukturen schaffen.','Erschütterungen sind nicht automatisch befreiend. Sie können Angst, Trauer und reale Verluste bedeuten. Sicherheit und Begleitung haben Vorrang vor vorschneller Sinnsuche.','["Was trägt nicht mehr?", "Was braucht jetzt zuerst Schutz oder Stabilisierung?", "Welche Wahrheit wird sichtbar - und was bleibt noch unklar?"]','Was möchtest du bewahren, auch wenn sich die Struktur verändert?','Du könntest zuerst für Sicherheit sorgen und erst danach entscheiden, was neu aufgebaut werden soll.','draft-review'),
('major-17','ADULT','de','0.1.0','Der Stern','Ein leises Licht für den weiteren Weg',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Stern erscheint nach einer Erschütterung. Er steht für Hoffnung, Echtheit und Regeneration - nicht als Garantie, sondern als Möglichkeit, wieder Orientierung zu spüren.','Hoffnung kann eine kleine, verlässliche Verbindung zum Morgen sein. Verletzlichkeit und Ruhe dürfen Teil von Heilung und Neuorientierung sein.','Hoffnung kann Druck erzeugen, wenn Schmerz zu schnell überwunden werden soll. Regeneration hat keinen allgemeinen Zeitplan.','["Was gibt dir leise Hoffnung?", "Wo kannst du gerade unverstellt sein?", "Welche Form von Regeneration ist heute erreichbar?"]','Welches kleine Licht möchtest du nicht übersehen?','Du könntest eine einzige Quelle von Hoffnung oder Erholung bewusst aufsuchen.','draft-review'),
('major-18','ADULT','de','0.1.0','Der Mond','Durch Unklarheit navigieren',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Der Mond verändert Konturen. Gefühle, Erinnerungen und Vorstellungen können stärker wirken, während eindeutige Antworten fehlen. Die Karte lädt zum Wahrnehmen ein, nicht zum vorschnellen Schluss.','Imagination und Sensibilität können Zugänge zu inneren Themen eröffnen. Nicht alles muss sofort verstanden werden, um ernst genommen zu werden.','Unklarheit kann Angst verstärken. Gefühle sind real, aber nicht jede daraus entstehende Erklärung muss zutreffen. Zusätzliche Orientierung kann hilfreich sein.','["Was ist gerade Gefühl, Beobachtung oder Vermutung?", "Welche Unsicherheit darf vorerst bestehen bleiben?", "Was würde dir mehr Orientierung oder Sicherheit geben?"]','Wie verändert der Mond heute deinen Blick auf die Landschaft?','Du könntest deine Wahrnehmungen notieren und Bewertungen zunächst davon trennen.','draft-review'),
('major-19','ADULT','de','0.1.0','Die Sonne','Sichtbar werden und Lebendigkeit spüren',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Die Sonne beleuchtet, wärmt und macht sichtbar. Sie kann Freude, Klarheit, Spiel und das Bedürfnis zeigen, sich nicht länger klein machen zu müssen.','Lebendigkeit darf ohne Leistung entstehen. Sichtbarkeit kann Verbindung ermöglichen und Erfolge dürfen anerkannt werden.','Helligkeit kann auch zu viel sein. Nicht jeder Mensch möchte immer sichtbar sein, und Freude muss nicht vorgeführt werden. Schutz und Rückzug bleiben berechtigte Bedürfnisse.','["Was möchte heute leuchten?", "Welche Form von Sichtbarkeit fühlt sich sicher an?", "Wo darf Freude einfach Freude sein?"]','Wie fühlt sich Lebendigkeit in deinem Körper und deinem Alltag an?','Du könntest einen Moment von Freude oder Gelingen bewusst wahrnehmen, ohne ihn vergrößern zu müssen.','draft-review'),
('major-20','ADULT','de','0.1.0','Das Gericht','Einen Ruf hören und neu entscheiden',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Das Gericht kann den Moment beschreiben, in dem frühere Erfahrungen in einem neuen Zusammenhang erscheinen. Eine Erkenntnis lädt dazu ein, die eigene Geschichte anders weiterzuführen.','Selbsterkenntnis kann Handlungsspielraum erweitern. Du darfst frühere Entscheidungen mit dem Wissen und den Bedingungen von damals betrachten und heute neu wählen.','Rückblick kann in Selbstverurteilung umschlagen. Entwicklung bedeutet nicht, die frühere Version deiner selbst abzuwerten. Verantwortung und Mitgefühl können zusammengehören.','["Welche Erkenntnis kehrt gerade wieder?", "Was wusstest oder konntest du damals noch nicht?", "Welche Entscheidung möchtest du heute neu treffen?"]','Welcher Ruf gehört wirklich zu dir - und welcher kommt von außen?','Du könntest eine alte Entscheidung neu betrachten, ohne deine damalige Wirklichkeit zu verleugnen.','draft-review'),
('major-21','ADULT','de','0.1.0','Die Welt','Ankommen, ohne stehen bleiben zu müssen',NULL,'Bevor du weiterliest: Was zieht deinen Blick zuerst an? Welche Stimmung, Bewegung oder Einzelheit bemerkst du?','Die Welt steht für Ganzheit, Abschluss und Verbundenheit. Eine Reise oder Entwicklungsphase darf als vollständig anerkannt werden, auch wenn das Leben weitergeht.','Ankommen ermöglicht Würdigung. Verschiedene Erfahrungen können Teil eines Ganzen sein, ohne Widersprüche vollständig aufzulösen.','Vollendung kann unter Druck setzen, wenn nur perfekte Ergebnisse zählen. Ein Abschluss darf unvollkommen sein und trotzdem Bedeutung haben.','["Was möchtest du als vollendet anerkennen?", "Welche Teile deiner Reise gehören heute zusammen?", "Wie möchtest du diesen Übergang würdigen?"]','Was bedeutet Ankommen für dich, wenn Bewegung weiterhin möglich bleibt?','Du könntest innehalten und benennen, was du auf diesem Weg gelernt, getragen oder verändert hast. Quellen- und Nutzungsnotiz Fachliche private Referenz: „Mystische Katzen“ (Handbuch und OCR-Auszug, bereitgestellt im August 2026). Dieses Dokument ist keine Transkription. Die Kartenstruktur folgt der etablierten Tarot-Systematik; sämtliche Kartenräume, Kontextfragen und Handlungsimpulse wurden eigenständig für NeuroBalance in NeuroWays-Sprache formuliert. Die Texte dienen der Selbstreflexion. Sie ersetzen keine medizinische, psychologische, rechtliche oder andere professionelle Beratung und enthalten keine Vorhersagen.','draft-review')
